=== default.nix ===
{
  bsv,
  build,
  host ? build,
  config ? "MinSizeRel",
}:
assert config == "Debug" || config == "MinSizeRel" || config == "NoLicense";
let
  lib = bsv.lib;
  repositories = import ../repositories.nix;
  isDebug = config == "Debug";
  preset = "${host.name}-${config}";

  copilot-top-driver = import ./copilot-top-driver/default.nix {
    inherit
      bsv
      build
      host
      config
      ;
  };

  copilot-gen-api = import ./copilot-gen-api/default.nix {
    inherit
      bsv
      build
      host
      config
      ;
  };

  copilot-gen-gas = import ./copilot-gen-gas/default.nix {
    inherit
      bsv
      build
      host
      config
      ;
  };

  copilot-gen-openocd = import ./copilot-gen-openocd/default.nix {
    inherit
      bsv
      build
      host
      config
      ;
  };

  copilot-gen-llvm = import ./copilot-gen-llvm/default.nix {
    inherit
      bsv
      build
      host
      config
      ;
  };

  copilot_23_46 = import ./copilot_23_46/default.nix {
    inherit
      bsv
      build
      host
      config
      ;
  };

  copilot_25_27 = import ./copilot_25_27/default.nix {
    inherit
      bsv
      build
      host
      config
      ;
  };

  copilot_45 = import ./copilot_45/default.nix {
    inherit
      bsv
      build
      host
      config
      ;
  };

  copilot-rlm-client = import ./copilot-rlm-client/default.nix {
    inherit
      bsv
      build
      host
      config
      ;
  };

  # `all` is a pure assembly derivation: copy from dependencies and shape the
  # final tree. No network/toolchain work happens here.
  all = lib.bwrapDerivation {
    name = "${build.system}.${host.name}.andes.copilot.${config}";

    root = [
      build.stdenv-nocc
    ];

    env = {
      inherit (build) PATH;
    };

    builder = lib.bashBuilder ''
      PRESET_DIR="$out/${preset}"

      mkdir --parents "$PRESET_DIR"

      # The three architecture families each keep their own payload root.
      cp --archive ${copilot_23_46}/. "$PRESET_DIR/23_46/"
      cp --archive ${copilot_25_27}/. "$PRESET_DIR/25_27/"
      cp --archive ${copilot_45}/. "$PRESET_DIR/45/"
      chmod --recursive u+w "$PRESET_DIR/23_46" "$PRESET_DIR/25_27" "$PRESET_DIR/45"

      mkdir --parents "$PRESET_DIR/23_46/bin" "$PRESET_DIR/25_27/bin" "$PRESET_DIR/45/bin"

      # Shared generated helper binaries are replicated into every family.
      cp ${copilot-gen-api}/api${host.EXEEXT} "$PRESET_DIR/23_46/bin/api${host.EXEEXT}"
      cp ${copilot-gen-gas}/as${host.EXEEXT} "$PRESET_DIR/23_46/bin/as${host.EXEEXT}"
      cp ${copilot-gen-openocd}/dbg${host.EXEEXT} "$PRESET_DIR/23_46/bin/dbg${host.EXEEXT}"
      cp ${copilot-gen-llvm}/llvm-20${host.EXEEXT} "$PRESET_DIR/23_46/bin/llvm-20${host.EXEEXT}"

      cp ${copilot-gen-api}/api${host.EXEEXT} "$PRESET_DIR/25_27/bin/api${host.EXEEXT}"
      cp ${copilot-gen-gas}/as${host.EXEEXT} "$PRESET_DIR/25_27/bin/as${host.EXEEXT}"
      cp ${copilot-gen-openocd}/dbg${host.EXEEXT} "$PRESET_DIR/25_27/bin/dbg${host.EXEEXT}"
      cp ${copilot-gen-llvm}/llvm-20${host.EXEEXT} "$PRESET_DIR/25_27/bin/llvm-20${host.EXEEXT}"

      cp ${copilot-gen-api}/api${host.EXEEXT} "$PRESET_DIR/45/bin/api${host.EXEEXT}"
      cp ${copilot-gen-gas}/as${host.EXEEXT} "$PRESET_DIR/45/bin/as${host.EXEEXT}"
      cp ${copilot-gen-openocd}/dbg${host.EXEEXT} "$PRESET_DIR/45/bin/dbg${host.EXEEXT}"
      cp ${copilot-gen-llvm}/llvm-20${host.EXEEXT} "$PRESET_DIR/45/bin/llvm-20${host.EXEEXT}"

      # Top-level launch entrypoints.
      mkdir --parents "$PRESET_DIR/bin"
      cp ${copilot-top-driver}/copilot${host.EXEEXT} "$PRESET_DIR/bin/copilot${host.EXEEXT}"
      cp ${copilot-rlm-client}/bin/lc${host.EXEEXT} "$PRESET_DIR/bin/lc${host.EXEEXT}"

      # Assemble init.lua by concatenating the cpu-mapping data file in
      # front of copilot-control-flow's init.lua template. This mirrors
      # what control_flow's CMakeLists.txt does at configure time
      # (`cat cpu_copilot_mapping.lua init.lua > init.lua`); init.lua
      # opens with `local cpu_copilot_mapping = cpu_copilot_mapping or {}`
      # so it shadow-or-defaults onto the prepended table.
      cat ${repositories.copilot-cpu-mapping}/cpu_copilot_mapping.lua \
          ${repositories.copilot-control-flow}/init.lua \
          > ./init.lua

      # Debug keeps a readable script for troubleshooting.
      # Release/NoLicense stores encrypted payload via encrypt_config.
      ${
        if isDebug then
          ''
            install -Dm644 ./init.lua "$PRESET_DIR/bin/init.lua"
          ''
        else
          ''
            ${build.andes.copilot.copilot-encrypt-config}/encrypt_config \
              --init=./init.lua \
              --output="$PRESET_DIR/bin/init"
          ''
      }
    '';

    outputChecks.out.allowedRequisites = [ "out" ];

    system = build.system;
  };

  dist = lib.bwrapDerivation {
    name = "${build.system}.${host.name}.andes.copilot.${config}.dist";

    root = [ build.stdenv-nocc ];

    env = {
      inherit (build) PATH;
    };

    builder = lib.bashBuilder ''
      mkdir --parents "$out"

      tar --create --gzip \
        --owner=0 --group=0 --mode=u+w \
        --file "$out/${preset}.tar.gz" \
        --directory=${all} \
        ${preset}
    '';

    system = build.system;
  };
in
all
// {
  recurseForDerivations = true;

  inherit
    copilot-top-driver
    copilot-gen-api
    copilot-gen-gas
    copilot-gen-openocd
    copilot-gen-llvm
    copilot_23_46
    copilot_25_27
    copilot_45
    copilot-rlm-client
    dist
    ;
}
