=== mk-copilot-payload.nix ===
{
  bsv,
  build,
  host ? build,
  config ? "MinSizeRel",
  variant,
  src,
}:
assert config == "Debug" || config == "MinSizeRel" || config == "NoLicense";
let
  lib = bsv.lib;

  isRelease = config != "Debug";
  cmakeBuildType = if config == "Debug" then "Debug" else "MinSizeRel";
  cmakeExeLinkerFlags = if isRelease then "-static -static-libgcc -static-libstdc++" else "";
  enableSecurityToken = if isRelease then "ON" else "OFF";

  isMingw = host.triple == "x86_64-w64-mingw32";
in
lib.bwrapDerivation {
  name = "${build.system}.${host.name}.andes.copilot.${config}.${variant}";

  root = [
    build.stdenv
    build.cmake
    build.perl
    build.m4
    build.bison
    build.flex
    host.zlib
  ]
  ++ (if build.triple != host.triple then [ build."${host.name}-toolchain" ] else [ ]);

  env = {
    inherit src;
    inherit (build) PATH;
    inherit (host)
      CC
      CXX
      AR
      CFLAGS
      LDFLAGS
      STRIP
      ;
    # verible's build_script.sh un-tars flex/bison/m4 sources and calls
    # tar --same-owner by default, which fails in the build sandbox
    # ("Cannot change ownership to uid 1000, gid 1000: Invalid argument").
    TAR_OPTIONS = "--no-same-owner";
  };

  builder = lib.bashBuilder ''
    # Work in writable source copy; upstream scripts modify tree in-place.
    cp --archive $src ./copilot-src
    chmod --recursive u+w copilot-src

    # mingw cross builds pass -DUSE_VERIBLE_PARSER=OFF -DDISABLE_RTL=ON, so
    # verible (and its flex/bison/m4 deps) is unused there — skip the build.
    ${
      if !isMingw then
        ''
          echo "=== Building verible external deps ==="
          pushd ./copilot-src/tool/verible.git >/dev/null
          # Pre-symlink the bsv-packaged m4/flex/bison into external/install/bin/
          # so build_script.sh sees them already present and skips re-building
          # them from source (the autotools/m4 build is the slow part). Only
          # abseil/grpc still get built and land in external/install/lib64/;
          # bridge that with the lib -> lib64 symlink for copilot's tool/CMakeLists.
          mkdir --parents external/install/bin
          ln --symbolic --force "$(type -P m4)"    external/install/bin/m4
          ln --symbolic --force "$(type -P flex)"  external/install/bin/flex
          ln --symbolic --force "$(type -P bison)" external/install/bin/bison
          ./build_script.sh ./verible-build "$CC" "$CXX" "$AR"
          ln --symbolic --force lib64 external/install/lib
          popd >/dev/null
        ''
      else
        ""
    }

    cmake -S ./copilot-src -B ./build -G "Unix Makefiles" \
      -D CMAKE_INSTALL_PREFIX=$out \
      -D CMAKE_BUILD_TYPE=${cmakeBuildType} \
      -D CMAKE_EXE_LINKER_FLAGS="${cmakeExeLinkerFlags}" \
      -D ENABLE_SECURITY_TOKEN_VALIDATION=${enableSecurityToken} \
      -D USE_HOST_TOOLCHAIN=ON \
      -D FLEX_EXECUTABLE="$(command -v flex)" \
      -D AR_EXECUTABLE="$(command -v "$AR")" \
      -D GCC_EXECUTABLE="$(command -v "$CC")" \
      -D GXX_EXECUTABLE="$(command -v "$CXX")" \
      -D GIT_HASH=${src.rev or ""} \
      ${
        if isMingw then
          ''
            -D CMAKE_TOOLCHAIN_FILE=${build."${host.name}-cmake-toolchain-file"} \
            -D CMAKE_SYSTEM_NAME=Windows \
            -D USE_VERIBLE_PARSER=OFF \
            -D DISABLE_RTL=ON \
          ''
        else
          ""
      } \
      ;

    cmake --build ./build \
      --config ${cmakeBuildType} \
      --target install \
      --parallel ''${NIX_BUILD_CORES} \
      ;

    ${if isRelease then ''$STRIP "$out/bin/copilot${host.EXEEXT}"'' else ""}
  '';

  unsafeDiscardReferences.out = true;

  outputChecks.out.allowedRequisites = [ "out" ];

  system = build.system;
}
=== mk-gen-rust-bin.nix ===
{
  bsv,
  build,
  host ? build,
  config ? "MinSizeRel",
  # Per-binary variation.
  subpackage, # e.g. "copilot-gen-api"
  src, # fetched source tree
  binName, # cargo --bin= target, e.g. "api"
  feature, # cargo --features= value for release builds; Debug skips it
}:
# Rust cargo binary builder shared by copilot-gen-{api,gas,openocd,llvm}.
assert config == "Debug" || config == "MinSizeRel" || config == "NoLicense";
let
  lib = bsv.lib;

  isRelease = config != "Debug";
  profile = if isRelease then "release" else "dev";
  artifact-dir = "${host.rustTarget}/${if profile == "dev" then "debug" else profile}";
in
lib.bwrapDerivation {
  name = "${build.system}.${host.name}.andes.copilot.${config}.${subpackage}";

  root = [
    build.stdenv
    build.ca-certificates
    build.cargo
    build.libz
    build.rust-std
    build.rustc
    build."${host.name}-toolchain"
    host.rust-std
  ];

  env = {
    inherit src;
    inherit (build) PATH;
    inherit (host)
      CC
      CFLAGS
      LDFLAGS
      STRIP
      ;
    VERGEN_GIT_SHA = src.rev or "";
  };

  builder = lib.bashBuilder ''
    cargo build \
      --bin=${binName} \
      --features=${if isRelease then feature else ""} \
      --jobs=''${NIX_BUILD_CORES} \
      --locked \
      --manifest-path=$src/Cargo.toml \
      --profile=${profile} \
      --target-dir=. \
      --target=${host.rustTarget} \
      ;

    install -Dm755 ${artifact-dir}/${binName}${host.EXEEXT} $out/${binName}${host.EXEEXT}
    ${if isRelease then "$STRIP $out/${binName}${host.EXEEXT}" else ""}
  '';

  unsafeDiscardReferences.out = true;

  outputChecks.out.allowedRequisites = [ "out" ];

  # Cargo may need network for registry/index as pinned by lockfile.
  shareNet = true;

  system = build.system;
}

