{
  bsv,
  build,
}:
let
  lib = bsv.lib;

  repositories = import ../../pkgs/andes/repositories.nix;
  copilot-all = build.andes.copilot.NoLicense;
  copilot-demo = repositories.copilot-demo;
  copilot-host-tools = "${repositories.copilot-host-tools-dev}/x86_64-pc-linux-gnu";

  preset = "x86_64-linux-gnu-NoLicense";
in
lib.bwrapDerivation {
  name = "${build.system}.${build.name}.tests.copilot";

  root = [
    build.stdenv-nocc
  ];

  env = {
    inherit (build) PATH;
    COPILOT_HOST_TOOLS = copilot-host-tools;
  };

  builder = lib.bashBuilder ''
    cp ${copilot-demo}/46series/AX46MPV/test_ace/test_inst.ace .

    timeout --foreground --verbose 60 \
      ${copilot-all}/${preset}/bin/copilot test_inst.ace

    # Copy generated outputs to $out.
    mkdir --parents "$out"
    cp --recursive lib include ide "$out/"
  '';

  system = build.system;
}
